package handlers.skill.effects;

import java.util.ArrayList;
import java.util.List;

import org.l2jmobius.gameserver.entity.actor.Creature;
import org.l2jmobius.gameserver.entity.item.instance.Item;
import org.l2jmobius.gameserver.mechanics.effects.AbstractEffect;
import org.l2jmobius.gameserver.mechanics.skill.Skill;
import org.l2jmobius.gameserver.mechanics.skill.holders.SkillHolder;
import org.l2jmobius.gameserver.util.StatSet;

/**
 * This class handles the application of various effects triggered by a {@code Skill}.<br>
 * It processes and executes the mechanics associated with specific skill instances.<br>
 * Use this class to manage how skills interact with {@code Creature} entities.
 * @author Mobius
 */
public class ApplySkillEffects extends AbstractEffect
{
	private final List<SkillHolder> _skills = new ArrayList<>();
	
	/**
	 * Creates a new effect that applies specific skills.<br>
	 * It parses skill data from the provided {@code StatSet}.
	 * @param params The {@code StatSet} containing the skill strings.
	 */
	public ApplySkillEffects(StatSet params)
	{
		final String skills = params.getString("skills", null);
		if (skills != null)
		{
			for (String skill : skills.split(";"))
			{
				_skills.add(new SkillHolder(Integer.parseInt(skill.split(",")[0]), Integer.parseInt(skill.split(",")[1])));
			}
		}
	}
	
	/**
	 * Checks if the effect is triggered instantly.<br>
	 * This method always returns {@code true}.
	 * @return {@code true} if the effect is instant.
	 */
	@Override
	public boolean isInstant()
	{
		return true;
	}
	
	/**
	 * Applies all skills associated with this effect immediately.<br>
	 * This method iterates through the internal skill list and triggers their effects.
	 * @param effector The {@code Creature} performing the action.
	 * @param effected The {@code Creature} receiving the action.
	 * @param skill The {@code Skill} being used.
	 * @param item The {@code Item} involved in the action.
	 */
	@Override
	public void instant(Creature effector, Creature effected, Skill skill, Item item)
	{
		for (SkillHolder holder : _skills)
		{
			final Skill appliedSkill = holder.getSkill();
			if (appliedSkill != null)
			{
				appliedSkill.applyEffects(effector, effected);
			}
		}
	}
}
